def variants(s):
  pts=sorted(s)
  out=[]
  cur=pts
  for _ in range(4):
    # rotate 90: (i,j)->(j,-i)
    mi=min(p[0] for p in cur); mj=min(p[1] for p in cur)
    cur=[(p[1]-mj,-(p[0]-mi)) for p in cur]
    mi=min(p[0] for p in cur); mj=min(p[1] for p in cur)
    out.append(frozenset((p[0]-mi,p[1]-mj) for p in cur))
    out.append(frozenset((a, -b) for a,b in out[-1]))
    m=min(b for a,b in out[-1]); out[-1]=frozenset((a,b-m) for a,b in out[-1])
  return out
