def bbox(grid, cells):
    """The block (subgrid) of the grid spanning the bounding box of the given cells."""
    ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
    return [grid[r][min(xs):max(xs)+1] for r in range(min(ys),max(ys)+1)]

def clear_block(grid, top, left, height, width):
    """Zero out the height x width block whose top-left cell is (top, left)."""
    return [[0 if top<=i<top+height and left<=j<left+width else v for j,v in enumerate(row)] for i,row in enumerate(grid)]

